      {
        "source_id": "new-0",
        "side": "new",
        "speaker": "user",
        "text": "I've been feeling quite relieved lately because my consulting firm finally secured some initial clients. It's a significant milestone for me.",
        "recorded_at": "Jan 05, 2026, 07:43:42",
